
public class ExpressoesAritimeticas {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int x, z, y;
		y = 4 + 5;
		System.out.println("Soma => 4 + 5 e: " + y);

		y = 10 - 5;
		System.out.println("Subtração => 10 - 5 e: " + y);

		y = 10 * 5;
		System.out.println("Multiplicação => 10 * 5 e: " + y);

		y = 10 / 5;
		System.out.println("Divisao => 10 / 5 e: " + y);
		
		y = 10 % 3; //De proposito fazer uma divisao nao exata, pra ter resto
		System.out.println("Modulo ou Resto => 10 % 3 e: " + y);
		
		

	}

}
